/* gộp học sinh trùng họ tên trong cùng lớp (không kể tên đăng nhập): chuyển kết quả về một tài khoản */
merge_students: req => withLock_(() => {
  const t = auth_(req, 'gv');
  const c = ownClass_(t, req.code);
  const key = s => String(s || '').normalize('NFC').toLowerCase().replace(/\s+/g, ' ').trim();
  const hs = rows_('HocSinh').filter(h => h.MaLop === c.MaLop), kq = rows_('KetQua'), nv = rows_('NopVe');
  const col = (name, f) => { const sh = sheet_(name); return [sh, sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0].map(String).indexOf(f) + 1]; };
  const [shK, cK] = col('KetQua', 'MaHS'), [shN, cN] = col('NopVe', 'MaHS');
  const groups = {}, del = [];
  hs.forEach(h => { const k = key(h.HoTen); if (k) (groups[k] = groups[k] || []).push(h); });
  Object.keys(groups).forEach(k => {
    const g = groups[k]; if (g.length < 2) return;
    const cnt = h => kq.filter(r => r.MaHS === h.MaHS).length;
    g.sort((a, b) => cnt(b) - cnt(a) || (new Date(a.NgayTao) - new Date(b.NgayTao)));
    const keep = g[0];
    g.slice(1).forEach(h => {
      kq.filter(r => r.MaHS === h.MaHS).forEach(r => shK.getRange(r._r, cK).setValue(keep.MaHS));
      if (cN > 0) nv.filter(r => r.MaHS === h.MaHS).forEach(r => shN.getRange(r._r, cN).setValue(keep.MaHS));
      if (!keep.Email && h.Email) { update_('HocSinh', keep._r, { Email: h.Email }); keep.Email = h.Email; }
      del.push(h);
    });
  });
  const sh = sheet_('HocSinh');
  del.sort((a, b) => b._r - a._r).forEach(h => sh.deleteRow(h._r));
  return { merged: del.length };
}),
/* đếm lượt truy cập */
hit: req => {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(3000)) return {};
  try {
    const p = PropertiesService.getScriptProperties(), d = Utilities.formatDate(new Date(), 'Asia/Ho_Chi_Minh', 'yyyyMMdd');
    const total = Number(p.getProperty('VISIT_TOTAL') || 0) + 1, today = p.getProperty('VISIT_DAY') === d ? Number(p.getProperty('VISIT_TODAY') || 0) + 1 : 1;
    p.setProperties({ VISIT_TOTAL: String(total), VISIT_DAY: d, VISIT_TODAY: String(today) });
    return { total: total, today: today };
  } finally { lock.releaseLock(); }
},
